// Outline JSON parsen und Sektionen als einzelne Items aufbereiten
const input = $input.all()[0].json;
let outline;
try {
  outline = typeof input.outline_json === 'string' ? JSON.parse(input.outline_json) : input.outline_json;
} catch(e) {
  // Fallback: versuche aus Markdown-Block zu parsen
  const match = (input.outline_json || '').match(/```(?:json)?\s*([\s\S]*?)```/);
  outline = match ? JSON.parse(match[1].trim()) : { sections: [], title_suggestion: input.keyword };
}

const sections = outline.sections || [];
const totalSections = sections.length;

// Jede Sektion als separates Item für den Loop
return sections.map((section, index) => ({
  json: {
    section_index: index,
    total_sections: totalSections,
    h2: section.h2 || '',
    h3_subsections: JSON.stringify(section.h3_subsections || []),
    infographic: JSON.stringify(section.infographic || null),
    key_points: JSON.stringify((section.h3_subsections || []).flatMap(s => s.key_points || [])),
    wdf_idf_terms_section: JSON.stringify((section.h3_subsections || []).flatMap(s => s.wdf_idf_terms || [])),
    internal_link: JSON.stringify((section.h3_subsections || []).map(s => s.internal_link).filter(Boolean)),
    title_suggestion: outline.title_suggestion || '',
    faq_section: JSON.stringify(outline.faq_section || []),
    all_internal_links: JSON.stringify(outline.internal_links || [])
  }
}));

// Claude-Antwort extrahieren
const items = $input.all();
return items.map((item, index) => {
  const content = item.json.content?.[0]?.text || item.json.choices?.[0]?.message?.content || '';
  return {
    json: {
      section_index: index,
      section_content: content
    }
  };
});

// Alle Sektionen zu einem Gesamtartikel zusammenfügen
const sections = $input.all()
  .sort((a, b) => a.json.section_index - b.json.section_index)
  .map(item => item.json.section_content);

const fullDraft = sections.join('\n\n---\n\n');

return [{ json: { full_draft: fullDraft, section_count: sections.length } }];

// Finalen Artikel extrahieren
const response = $input.all()[0].json;
const finalArticle = response.content?.[0]?.text || '';

return [{ json: { final_article: finalArticle } }];

// FAQ-Sektion aus dem Outline generieren (falls vorhanden)
const outlineJson = $('Extract Input Data').item.json.outline_json;
let outline;
try {
  outline = typeof outlineJson === 'string' ? JSON.parse(outlineJson) : outlineJson;
} catch(e) { outline = { faq_section: [] }; }

const faqItems = outline.faq_section || [];
if (faqItems.length === 0) {
  return [{ json: { faq_markdown: '', has_faq: false } }];
}

let faqMd = '\n\n## Häufig gestellte Fragen (FAQ)\n\n';
for (const faq of faqItems) {
  faqMd += `### ${faq.question}\n\n${faq.answer_outline}\n\n`;
}

return [{ json: { faq_markdown: faqMd, has_faq: true, faq_count: faqItems.length } }];

// Meta-Daten parsen
const response = $input.all()[0].json;
const content = response.content?.[0]?.text || '';

let meta;
try {
  meta = JSON.parse(content);
} catch(e) {
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    try { meta = JSON.parse(jsonMatch[1].trim()); } catch(e2) { meta = null; }
  }
  if (!meta) {
    const braceMatch = content.match(/\{[\s\S]*\}/);
    meta = braceMatch ? JSON.parse(braceMatch[0]) : {
      meta_title: $('Extract Input Data').item.json.keyword,
      meta_description: '',
      url_slug: ($('Extract Input Data').item.json.keyword || '').toLowerCase().replace(/[^a-z0-9]+/g, '-'),
      focus_keyword: $('Extract Input Data').item.json.keyword
    };
  }
}

// FAQ-Daten
let faqData = { has_faq: false, faq_markdown: '' };
try { faqData = $('Build FAQ Section').item.json; } catch(e) {}

// Artikel vom Style Pass
const finalArticle = $('Extract Final Article').item.json.final_article || '';

const fullContent = faqData.has_faq ? finalArticle + faqData.faq_markdown : finalArticle;

return [{
  json: {
    meta: meta,
    full_content: fullContent,
    word_count: fullContent.split(/\s+/).length
  }
}];

// Prüfe ob ein bestehendes Google Doc übergeben wurde (von 01a/ClickUp)
const existingDocId = $('Extract Input Data').item.json.doc_id;
const existingDocUrl = $('Extract Input Data').item.json.doc_url;

if (existingDocId) {
  // Bestehendes Doc nutzen — kein neues erstellen
  return [{ json: { id: existingDocId, doc_url: existingDocUrl, used_existing: true } }];
} else {
  // Kein Doc vorhanden — Flag setzen, dass neues erstellt werden muss
  return [{ json: { id: '', doc_url: '', needs_creation: true } }];
}

// Doc-Daten zusammenführen (bestehendes oder neu erstelltes Doc)
const items = $input.all();
const item = items[items.length - 1].json;

const docId = item.id;
const docUrl = item.doc_url || `https://docs.google.com/document/d/${docId}/edit`;

// Content für Google Docs API vorbereiten
const content = $('Parse Meta & Assemble Final').item.json.full_content;
const meta = $('Parse Meta & Assemble Final').item.json.meta;

// Header mit Meta-Daten + Content
const fullText = `META TITLE: ${meta.meta_title}\nMETA DESCRIPTION: ${meta.meta_description}\nURL SLUG: ${meta.url_slug}\nFOCUS KEYWORD: ${meta.focus_keyword}\n\n${'='.repeat(60)}\n\n${content}`;

return [{
  json: {
    doc_id: docId,
    doc_url: docUrl,
    full_text: fullText
  }
}];

// Zusammenfassung
const meta = $('Parse Meta & Assemble Final').item.json.meta;
const wordCount = $('Parse Meta & Assemble Final').item.json.word_count;
const docUrl = $('Prepare Doc Content').item.json.doc_url;
const keyword = $('Extract Input Data').item.json.keyword;

return [{
  json: {
    success: true,
    keyword: keyword,
    meta_title: meta.meta_title,
    meta_description: meta.meta_description,
    url_slug: meta.url_slug,
    word_count: wordCount,
    google_doc_url: docUrl,
    message: `Content für "${keyword}" erstellt (${wordCount} Wörter). Doc: ${docUrl}`
  }
}];

// WDF*IDF Abdeckungsprüfung für den gesamten Beitrag
const article = $('Extract Final Article').item.json.final_article.toLowerCase();
const wdfTermsRaw = $('Extract Input Data').item.json.wdf_idf_terms_json;
let wdfTerms;
try {
  wdfTerms = typeof wdfTermsRaw === 'string' ? JSON.parse(wdfTermsRaw) : wdfTermsRaw;
} catch(e) { wdfTerms = []; }

if (!wdfTerms || wdfTerms.length === 0) {
  return [{ json: { wdf_idf_check: 'Keine WDF*IDF Terme vorhanden', coverage_pct: 0, missing_terms: [], found_terms: [] } }];
}

const found = [];
const missing = [];
for (const t of wdfTerms) {
  const term = (t.term || t).toLowerCase();
  if (article.includes(term)) {
    found.push({ term, score: t.score || 0 });
  } else {
    missing.push({ term, score: t.score || 0 });
  }
}

const coveragePct = Math.round((found.length / wdfTerms.length) * 100);

// Top 15 fehlende Terme (nach Score sortiert)
const topMissing = missing.sort((a, b) => b.score - a.score).slice(0, 15);

return [{
  json: {
    coverage_pct: coveragePct,
    found_count: found.length,
    total_terms: wdfTerms.length,
    missing_count: missing.length,
    top_missing_terms: topMissing.map(t => `${t.term} (${t.score})`).join(', '),
    found_terms: found.map(t => t.term),
    needs_optimization: coveragePct < 60
  }
}];

// Optimierten Artikel extrahieren und als final_article ersetzen
const response = $input.all()[0].json;
const optimizedArticle = response.content?.[0]?.text || $('Extract Final Article').item.json.final_article;

// Überschreibe final_article für die nachfolgenden Nodes
return [{ json: { final_article: optimizedArticle } }];

// Merge: nimmt optimierten Artikel falls vorhanden, sonst Original
const items = $input.all();
// Der letzte Input ist der richtige (entweder optimiert oder original)
const finalArticle = items[items.length - 1].json.final_article 
  || $('Extract Final Article').item.json.final_article;

return [{ json: { final_article: finalArticle } }];

// GEO-optimierten Artikel extrahieren
const response = $input.all()[0].json;
const geoArticle = response.content?.[0]?.text || $('Merge Article (Original or Optimized)').item.json.final_article;

return [{ json: { final_article: geoArticle } }];

// Build Claude Pass 1 request body safely
const sectionIndex = $json.section_index;
const totalSections = $json.total_sections;
const keyword = $('Extract Input Data').item.json.keyword || '';
const h2 = $json.h2 || '';
const h3Subsections = $json.h3_subsections || '[]';
const keyPoints = $json.key_points || '[]';
const wdfTermsSection = $json.wdf_idf_terms_section || '[]';
const internalLink = $json.internal_link || '[]';
const infographic = $json.infographic || 'null';
const wdfTerms = $('Extract Input Data').item.json.wdf_idf_terms || '';
const perplexityResearch = $('Extract Input Data').item.json.perplexity_research || '';
const targetWords = parseInt($('Config').item.json.target_word_count) || 2500;
const wordsPerSection = Math.round(targetWords / totalSections);

const userContent = `Schreibe Sektion ${sectionIndex + 1} von ${totalSections} eines umfassenden Blogartikels.

## KEYWORD
${keyword}

## DIESE SEKTION
H2: ${h2}
Untersektionen: ${h3Subsections}
Kernpunkte: ${keyPoints}
WDF*IDF Terme für diese Sektion: ${wdfTermsSection}
Interne Links: ${internalLink}

## INFOGRAFIK-PLATZIERUNG
${infographic}

## ZUSÄTZLICHER KONTEXT
WDF*IDF Terme gesamt: ${wdfTerms}

Perplexity Research (Fakten & Quellen):
${perplexityResearch}

## ANFORDERUNGEN
1. Schreibe NUR diese eine Sektion (H2 + alle H3-Untersektionen)
2. Ca. ${wordsPerSection} Wörter für diese Sektion
3. Integriere die WDF*IDF Terme natürlich in den Text
4. Verwende Fakten aus der Perplexity-Recherche mit konkreten Zahlen/Daten
5. Baue interne Links als Markdown-Links ein: [Ankertext](URL)
6. Bei Infografik-Platzierung: Füge einen Platzhalter ein: <!-- INFOGRAFIK: Beschreibung -->
7. Schreibe in Markdown (H2 = ##, H3 = ###)
8. Benutze Aufzählungen, Tabellen oder Infoboxen wo sinnvoll
9. KEIN Fazit am Ende der Sektion (außer es ist die letzte)
10. KEINE Einleitung die den ganzen Artikel zusammenfasst
11. EXTERNE LINKS: NUR zu offiziellen Statistiken, Gesetzestexten oder Behörden. KEINE Links zu Wettbewerbern oder kommerziellen Seiten. Im Zweifel KEINEN externen Link.
12. Übergänge zwischen Absätzen sollen natürlich fließen, KEINE KI-typischen Formulierungen

Schreibe NUR den Markdown-Content dieser Sektion, keine Erklärungen.`;

const SYSTEM_PROMPT = "# System Prompt: Versicherungsmakler Blog-Posts  Du bist ein unabh\u00e4ngiger Finanz- und Versicherungsexperte, der komplexe Themen rund um Versicherung und Finanzen f\u00fcr Privatpersonen, Familien und Selbstst\u00e4ndige aufbereitet.  Schreibe SEO-optimierte Blog-Posts im Ich-Stil: vertrauensvoll, direkt, auf Augenh\u00f6he. Erkl\u00e4re komplexe Sachverhalte einfach und nutze keine Fachbegriffe ohne Erkl\u00e4rung. Durchgehend du-Ansprache. Du, dich, dein und dir werden nur am Satzanfang gro\u00dfgeschrieben, nicht grunds\u00e4tzlich im ganzen Text.  ---  ## ZIEL  Kl\u00e4re komplexe Themen auf, betone Individualit\u00e4t und f\u00fchre nat\u00fcrlich zu einer kostenfreien Beratung. Keine Produktempfehlungen oder externen L\u00f6sungen. Vergleiche neutral.  ---  ## INPUT (strikt befolgen)  - SEO-Keyword, Tonalit\u00e4tsbriefing, Outline, Research - \u00dcbernimm alle Headlines exakt aus der Outline - Erfinde keine Fakten, nur Research-Daten verwenden  ---  ## STRUKTUR (exakt in dieser Reihenfolge)  1. **H1** (vorgegeben aus Outline)  2. **Einleitung** (keine \u00dcberschrift, 80\u2013100 W\u00f6rter)    - Ende mit: \u201eIn diesem Beitrag erf\u00e4hrst du\u2026\"  3. **Das Wichtigste in K\u00fcrze**    - Erst am Ende aus fertigem Artikel extrahieren    - Format: **Fetter Kernsatz:** Detaillierte Erkl\u00e4rung (3\u20135 Stichpunkte)  4. **Hauptinhalt**    - Alle H2 exakt aus Outline \u00fcbernehmen    - Nach jeder H2 mindestens ein Absatz Text bevor die erste H3 kommt    - Bei mehr als 250 W\u00f6rtern pro Abschnitt H3 oder H4 einf\u00fcgen  5. **Fazit: [Kernaussage]**    - Kernaussage = Essenz des Beitrags    - Nat\u00fcrlicher CTA zur kostenfreien Beratung im Text  6. **FAQ** (nur falls in Outline angegeben)  ---  ## KRITISCHE FORMATREGEL: H2 direkt vor H3  Nach jeder H2 muss mindestens ein vollst\u00e4ndiger Absatz mit 100\u2013200 W\u00f6rtern kommen, bevor die erste H3 erscheint. Der Leser braucht Kontext, bevor Details folgen.  \u274c Verboten: ``` ## Kosten im \u00dcberblick ### Private Krankenversicherung ```  \u2705 Richtig: ``` ## Kosten im \u00dcberblick Die Kosten einer Krankenversicherung h\u00e4ngen von vielen Faktoren ab. Dein Alter spielt dabei eine wichtige Rolle, genauso wie dein Gesundheitszustand. Je j\u00fcnger und ges\u00fcnder du bist, desto g\u00fcnstiger sind in der Regel die Tarife. Viele Menschen untersch\u00e4tzen diese Unterschiede, bis sie zum ersten Mal einen konkreten Vergleich sehen. [Mindestens 100 W\u00f6rter, besser 150\u2013200]  ### Private Krankenversicherung ```  **Vor der Ausgabe:** Durchsuche den fertigen Artikel und pr\u00fcfe jede einzelne H2. Folgt danach sofort eine H3, f\u00fcge einen Einleitungsabsatz ein.  ---  ## \u00dcBERSCHRIFTEN (H3/H4)  ### Wann H3 oder H4 einf\u00fcgen  Bei Abschnitten \u00fcber 250 W\u00f6rtern und zur logischen Aufteilung von Inhalten.  ### Format  **Imperativ mit du:** - \u201ePr\u00fcf deine Optionen\" - \u201eNimm dir Zeit f\u00fcr den Gesundheitsfragebogen\" - \u201eLass falsche Angaben korrigieren\"  **Knappe 2\u20133-Wort-Beschreibung:** - \u201eBewusste T\u00e4uschung\" - \u201eKosten\u00fcberblick\" - \u201eVersehentliche Falschangaben\"  ### Verboten bei \u00dcberschriften  - Keine ausf\u00fchrlichen S\u00e4tze - Nie mit Der, Die oder Das beginnen - Bei Fragen in der \u00dcberschrift niemals mit einer Doppelpunkt-Konstruktion im darauffolgenden Absatz beginnen  ---  ## SPRACHSTIL UND TONALIT\u00c4T  ### Grundhaltung  Schreibe wie ein erfahrener Berater, der einem besch\u00e4ftigten aber interessierten Leser schnell Klarheit verschafft. Auf Augenh\u00f6he, empathisch, an manchen Stellen leicht provozierend, aber immer sachlich und fachlich korrekt. Kein Smalltalk, keine \u00fcbertriebene H\u00f6flichkeit, keine Entschuldigungen. Ruhig, direkt, souver\u00e4n.  ### Satzrhythmus und Absatzl\u00e4nge  Kurze Abs\u00e4tze mit 2\u20134 S\u00e4tzen. S\u00e4tze lang genug f\u00fcr einen vollst\u00e4ndigen Gedanken, kurz genug zum schnellen Erfassen. Abwechslungsreich, flie\u00dfend, nie verschachtelt, nie Stakkato. Dynamischer Satzbau: mal k\u00fcrzer, mal etwas l\u00e4nger, maximal ein Nebensatz pro Hauptsatz. Konnektoren zwischen S\u00e4tzen einsetzen, zum Beispiel: deshalb, trotzdem, dabei, allerdings. Kein Satz unter 3\u20134 W\u00f6rtern. Der Sprachfluss soll nat\u00fcrlich und nahbar klingen, so als w\u00fcrde der Autor direkt mit dem Leser sprechen.  \u274c Zu abgehackt: \u201eHol dir deine Patientenakte. Pr\u00fcf deine Optionen. Ruf mich an.\"  \u274c Zu verschachtelt: \u201eDie private Krankenversicherung, die zwar initial g\u00fcnstiger erscheinen mag als die gesetzliche, entwickelt sich \u00fcber die Jahre hinweg zu einer finanziellen Herausforderung, weshalb man, wenn man sich daf\u00fcr entscheidet, von Anfang an eine durchdachte Strategie braucht.\"  \u2705 Richtig: \u201eHol dir deine Patientenakte und pr\u00fcf genau, was da drinsteht, denn jede vergessene Diagnose kann dich sp\u00e4ter teuer zu stehen kommen. Wenn du unsicher bist, meld dich gerne und wir schauen gemeinsam, welche Optionen du wirklich hast.\"  ### Aktive Sprache  Immer aktiv formulieren, nie passiv. Immer aus der Perspektive des Lesers sprechen.  \u2705 \u201eDie Versicherung k\u00fcndigte den Vertrag ohne Vorwarnung.\" \u2705 \u201eDu zahlst \u00fcber 1.000 \u20ac mehr im Jahr.\"  \u274c \u201eDer Vertrag wurde gek\u00fcndigt.\" \u274c \u201eEs werden \u00fcber 1.000 \u20ac mehr gezahlt.\"  ### Klare Positionierung  Keine Absicherungen, keine Weichmacher, keine Doppeldeutigkeit.  \u2705 \u201eDas ist ein Mythos.\" \u2705 \u201eSo funktioniert das nicht.\" \u2705 \u201eDas klingt hart, aber es bringt nichts, dir hier falsche Hoffnungen zu machen.\"  \u274c \u201eDas k\u00f6nnte eventuell schwierig werden.\" \u274c \u201eEs gibt m\u00f6glicherweise Einschr\u00e4nkungen.\" \u274c \u201eMan wei\u00df ja nie.\"  ### Dringlichkeit ohne Panik  Wenn etwas wichtig ist, direkt benennen. Keine \u00dcbertreibungen, keine Angstmache, keine Ausrufezeichen zur Dramatisierung.  \u2705 \u201eDie Beitragserh\u00f6hungen kommen jedes Jahr verl\u00e4sslich. Wenn du heute nicht vorsorgst, zahlst du in 20 Jahren deutlich mehr. Das ist keine Panikmache, sondern simple Mathematik.\"  \u274c \u201eACHTUNG! Wenn Sie nicht SOFORT handeln, werden Sie im Alter PLEITE sein!\"  ### Auf den Punkt kommen  Frag dich vor jedem Satz, ob er notwendig ist. Frag dich vor jedem Komma, ob der Nebensatz wirklich gebraucht wird. Nur einbauen, wenn es den Gedanken vervollst\u00e4ndigt. Direkt sagen, was gemeint ist, ohne Umschweife.  ---  ## ERFAHRUNG EINBAUEN  Texte, die erkennbar von einem Praktiker mit echten Erfahrungen geschrieben sind, wirken vertrauensw\u00fcrdiger. Die Erfahrung soll sp\u00fcrbar sein, ohne dass es nach Eigenwerbung klingt.  ### Einmalige Expertise-Aussage  Einmal pro Artikel die Erfahrung ausf\u00fchrlicher einbauen. Nur eine der folgenden Varianten verwenden, nie mehr als eine:  - \u201eIch bin seit \u00fcber [X] Jahren als Versicherungsberater unterwegs und sehe immer wieder, dass\u2026\" - \u201eAls unabh\u00e4ngiger Berater mit langj\u00e4hriger Erfahrung empfehle ich dir,\u2026\" - \u201eIch kann dir aus Erfahrung sagen, dass\u2026\"  ### Erfahrung subtil im Flie\u00dftext zeigen  Im restlichen Artikel die Erfahrung nur andeuten. Keine Formulierung kommt im selben Artikel zweimal vor:  - \u201eDas sehe ich oft bei meinen Kunden.\" - \u201eDas Thema landet oft bei mir auf dem Tisch.\" - \u201eDas ist einer der h\u00e4ufigsten Fehler, die mir in der Beratung begegnen.\" - \u201eMeine Kunden fragen mich das oft.\"  ### Beispiele einleiten  Jedes Beispiel braucht eine andere Einleitung. Keine Wiederholung im selben Artikel:  - \u201eSowas erlebe ich bei meinen Kunden st\u00e4ndig.\" - \u201eDazu einmal ein Beispiel.\" - \u201eStell dir mal folgende Situation vor:\" - \u201eDas Problem taucht leider h\u00e4ufig auf:\" - \u201eSchau dir das folgende Beispiel an.\"  Jedes Beispiel folgt dem Muster: **Situation \u2192 Problem \u2192 Konsequenz \u2192 L\u00f6sung.**  ---  ## VERBOTENE W\u00d6RTER UND KONSTRUKTIONEN  ### Direkt verboten  - \u201eman\" statt \u201edu\" - \u201ePraxis\", \u201eBeratungspraxis\" und alle Zusammensetzungen damit - \u201eumfassend\", \u201eganzheitlich\", \u201erevolutionieren\" - \u201eunterm Strich\", \u201ein der heutigen Zeit\", \u201eentscheidende Rolle\" - \u201ekomplex und vielschichtig\"  ### Verbotene Konstruktionen  - Passivkonstruktionen - Gedankenstriche (\u2013) oder Bindestriche (-) im Satzbau, durch Komma, Punkt oder Konnektor ersetzen - Emojis - Bindestriche als Satzzeichen - S\u00e4tze unter 3\u20134 W\u00f6rtern - \u201eHier\"-S\u00e4tze als Einleitung (z. B. \u201eHier ein \u00dcberblick:\") - Fettgedruckter Text als Pseudo-\u00dcberschrift (z. B. **Zahnbehandlung und Kieferorthop\u00e4die** ohne H-Tag) - Fette Label wie **Vorteil:** oder **Nachteil:** im Flie\u00dftext - Aufz\u00e4hlungen im Stil \u201ekeine X, sondern Y\" oder \u201enicht X, sondern Y\", stattdessen direkt sagen, was gemeint ist - Aufz\u00e4hlungen im Stil \u201ekeine, keine, keine\" oder \u201eohne, ohne, ohne\" - Konstruktionen wie \u201eklingt gut?\", \u201eklingt simpel?\", \u201eklingt komplex?\" und alle \u00e4hnlichen Varianten  ### Doppelpunkt-Konstruktionen  Doppelpunkte d\u00fcrfen nur nach maximal 2\u20133 W\u00f6rtern stehen. Pro Satz und pro Abschnitt maximal eine Doppelpunkt-Konstruktion. L\u00e4ngere Einleitungen vor einem Doppelpunkt m\u00fcssen in einen vollst\u00e4ndigen Satz umformuliert werden.  \u274c \u201eDie Antwort ist eindeutig: 15 % der Familien\u2026\" \u2705 \u201e15 % der Familien nutzen diese Option.\"  \u274c \u201eDie Zahlen sprechen eine klare Sprache: Jedes dritte Kind\u2026\" \u2705 \u201eJedes dritte Kind ben\u00f6tigt eine Zahnspange.\"  \u274c \u201eDas bedeutet:\", \u201eSpoiler:\", \u201eHinweis:\", \u201eMerke:\", \u201e\u00dcbrigens:\", \u201eAu\u00dferdem:\", \u201eDie gute Nachricht:\" \