    faq_section: JSON.stringify(outline.faq_section || []),
    all_internal_links: JSON.stringify(outline.internal_links || [])
  }
}));

// Claude-Antwort extrahieren
const items = $input.all();
return items.map((item, index) => {
  const content = item.json.content?.[0]?.text || item.json.choices?.[0]?.message?.content || '';
  return {
    json: {
      section_index: index,
      section_content: content
    }
  };
});

// Alle Sektionen zu einem Gesamtartikel zusammenfügen
const sections = $input.all()
  .sort((a, b) => a.json.section_index - b.json.section_index)
  .map(item => item.json.section_content);

const fullDraft = sections.join('\n\n---\n\n');

return [{ json: { full_draft: fullDraft, section_count: sections.length } }];

// Finalen Artikel extrahieren
const response = $input.all()[0].json;
const finalArticle = response.content?.[0]?.text || '';

return [{ json: { final_article: finalArticle } }];

// FAQ-Sektion aus dem Outline generieren (falls vorhanden)
const outlineJson = $('Extract Input Data').item.json.outline_json;
let outline;
try {
  outline = typeof outlineJson === 'string' ? JSON.parse(outlineJson) : outlineJson;
} catch(e) { outline = { faq_section: [] }; }

const faqItems = outline.faq_section || [];
if (faqItems.length === 0) {
  return [{ json: { faq_markdown: '', has_faq: false } }];
}

let faqMd = '\n\n## Häufig gestellte Fragen (FAQ)\n\n';
for (const faq of faqItems) {
  faqMd += `### ${faq.question}\n\n${faq.answer_outline}\n\n`;
}

return [{ json: { faq_markdown: faqMd, has_faq: true, faq_count: faqItems.length } }];

// Meta-Daten parsen
const response = $input.all()[0].json;
const content = response.content?.[0]?.text || '';

let meta;
try {
  meta = JSON.parse(content);
} catch(e) {
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    try { meta = JSON.parse(jsonMatch[1].trim()); } catch(e2) { meta = null; }
  }
  if (!meta) {
    const braceMatch = content.match(/\{[\s\S]*\}/);
    meta = braceMatch ? JSON.parse(braceMatch[0]) : {
      meta_title: $('Extract Input Data').item.json.keyword,
      meta_description: '',
      url_slug: ($('Extract Input Data').item.json.keyword || '').toLowerCase().replace(/[^a-z0-9]+/g, '-'),
      focus_keyword: $('Extract Input Data').item.json.keyword
    };
  }
}

// FAQ-Daten
